const fs=require('fs');
const workerPath='_worker.js';
let source=fs.readFileSync(workerPath,'utf8');
const marker='// bare-review-video-explicit-play-v1';
if(!source.includes(marker)){
source+=`\n\n${marker}\nconst bareReviewPlayStyle='<style id="bare-review-play-style">.bare-review-video-frame{position:relative!important}.bare-review-play{position:absolute;left:50%;top:50%;z-index:4;display:grid;place-items:center;width:72px;height:72px;border:1px solid rgba(255,255,255,.7);border-radius:50%;background:rgba(0,0,0,.72);color:#fff;font:900 0/1 Arial,sans-serif;cursor:pointer;transform:translate(-50%,-50%);transition:.18s}.bare-review-play:before{content:"";display:block;margin-left:6px;border-top:12px solid transparent;border-bottom:12px solid transparent;border-left:19px solid #fff}.bare-review-play.is-hidden{opacity:0;visibility:hidden;pointer-events:none}@media(max-width:860px){.bare-review-play{width:62px;height:62px}}</style>';\nconst bareReviewPlayScript='<script id="bare-review-play-script">(()=>{let timer=0;function bind(){document.querySelectorAll(".bare-review-video").forEach(video=>{if(video.dataset.explicitPlay==="1")return;video.dataset.explicitPlay="1";video.preload="auto";const frame=video.closest(".bare-review-video-frame");if(!frame)return;const button=document.createElement("button");button.type="button";button.className="bare-review-play";button.setAttribute("aria-label","리뷰 영상 재생");frame.appendChild(button);const show=()=>button.classList.remove("is-hidden"),hide=()=>button.classList.add("is-hidden");button.addEventListener("click",event=>{event.preventDefault();event.stopPropagation();video.play().then(hide).catch(()=>show())});video.addEventListener("play",hide);video.addEventListener("playing",hide);video.addEventListener("pause",()=>{if(!video.ended)show()});video.addEventListener("ended",show);video.addEventListener("error",show);if(!video.paused)hide()})}function queue(){clearTimeout(timer);timer=setTimeout(bind,50)}new MutationObserver(queue).observe(document.body,{childList:true,subtree:true});addEventListener("hashchange",queue);queue()})();<\\/script>';\nconst bareReviewPlayBase=patchHtml;\npatchHtml=function(html){return bareReviewPlayBase(html).replace('</head>',bareReviewPlayStyle+'</head>').replace('</body>',bareReviewPlayScript+'</body>')};\n`;
fs.writeFileSync(workerPath,source);
}
for(const path of ['.github/fix-review-video-play.cjs','.github/workflows/fix-review-video-play.yml'])if(fs.existsSync(path))fs.unlinkSync(path);
